using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B3Occlusion {
 public static object Bake(){if(Application.isPlaying||StaticOcclusionCulling.isRunning)throw new Exception("Idle edit required");StaticOcclusionCulling.GenerateInBackground();return new{running=StaticOcclusionCulling.isRunning};}
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-09_B3_FullFloor/";
 public static object Begin(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||StaticOcclusionCulling.isRunning||!s.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved idle B4 required");var root=s.GetRootGameObjects().Single(g=>g.name=="B3_Circular_SampleFloor").transform;if(root.Find("B3_OcclusionAreas"))throw new Exception("Already configured");int count=0;foreach(var mf in root.GetComponentsInChildren<MeshFilter>()){string a=AssetDatabase.GetAssetPath(mf.sharedMesh);if(!a.Contains("/Environment/B3/")||!(mf.name.EndsWith("_Shell")||mf.name.EndsWith("_Floor")||mf.name.EndsWith("_TunnelShell")))continue;GameObjectUtility.SetStaticEditorFlags(mf.gameObject,GameObjectUtility.GetStaticEditorFlags(mf.gameObject)|StaticEditorFlags.OccluderStatic|StaticEditorFlags.OccludeeStatic);count++;}
 var plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B3_FullFloor/layout.json"));var g=new GameObject("B3_OcclusionAreas");g.transform.SetParent(root,false);foreach(var r in plan["rooms"]){var v=new GameObject("View_"+(string)r["id"]);v.transform.SetParent(g.transform,false);float h=(string)r["kind"]=="core"?19:5;v.transform.localPosition=new Vector3((float)r["x"],h/2,-(float)r["v"]);v.AddComponent<OcclusionArea>().size=new Vector3((float)r["r"]*2,h,(float)r["r"]*2);}
 foreach(var t in plan["tunnels"]){var p=new Vector3((float)t["p"][0],1.6f,-(float)t["p"][1]);var q=new Vector3((float)t["q"][0],1.6f,-(float)t["q"][1]);var v=new GameObject("View_"+(string)t["id"]);v.transform.SetParent(g.transform,false);v.transform.localPosition=(p+q)/2;v.transform.localRotation=Quaternion.LookRotation(q-p);v.AddComponent<OcclusionArea>().size=new Vector3(4.2f,3.2f,Vector3.Distance(p,q)+1);}
 foreach(var c in s.GetRootGameObjects().SelectMany(a=>a.GetComponentsInChildren<Camera>(true)))c.useOcclusionCulling=true;
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);StaticOcclusionCulling.GenerateInBackground();var result=new{occluders=count,areas=g.transform.childCount,running=StaticOcclusionCulling.isRunning};File.WriteAllText(O+"occlusion_setup.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 public static object Status(){var result=new{running=StaticOcclusionCulling.isRunning,bytes=StaticOcclusionCulling.umbraDataSize};if(!result.running){var s=SceneManager.GetActiveScene();if(s.isDirty)EditorSceneManager.SaveScene(s);File.WriteAllText(O+"occlusion_result.json",JsonConvert.SerializeObject(result,Formatting.Indented));}return result;}
}
